template<class T>static std::vector<T> read29(const std::string&path){FILE*f=fopen(path.c_str(),"rb");need(f,"frozen typed packet");uint64_t h[8];need(fread(h,sizeof(h),1,f)==1&&h[0]==0x4753415749544e31ULL&&h[3]==sizeof(T),"same typed packet ABI");std::vector<T>v(h[4]);if(!v.empty())need(fread(v.data(),sizeof(T),v.size(),f)==v.size(),"complete typed records");need(fgetc(f)==EOF,"packet exact length");fclose(f);return v;}
struct Event29 {uint64_t slot,source,target,node,kind,passed,reused,inverse_index;S input[2],reference[2],lambda[3];char event[160],reason[192];};
struct Frame29 {uint64_t slot,source,target,chart,passed,active_mask;sd::Chart original;S apex[2],direction[2],transverse[2],determinant,corner[4][2],projected[4][2],derivative[23];Q cut;char reason[192];};
